"use client";

import { useMemo } from "react";
import { propsToDataAttrs } from "@/registry/nextjs/lib/utilities";
import "@/registry/nextjs/components/text-input/text-input.css";
import Icon from "@/registry/nextjs/components/icon";
import Row from "@/registry/nextjs/components/row";
import Text from "@/registry/nextjs/components/text";
import StateLayer from "@/registry/nextjs/components/state-layer";
import { IconName } from "lucide-react/dynamic";
import { useState, useEffect } from "react";
import { truncateSync } from "node:fs";
Text;

interface LkTextInputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  labelPosition?: "default" | "on-input";
  helpText?: string;
  placeholder?: string;
  name?: string;
  endIcon?: IconName;
  labelBackgroundColor?: LkColor;
}

export default function TextInput({
  labelPosition = "default",
  helpText,
  placeholder = "Placeholder",
  name = "Label",
  endIcon = "search",
  labelBackgroundColor,
  ...restProps
}: LkTextInputProps) {
  const textInputProps = useMemo(
    () => propsToDataAttrs({ labelPosition }, "text-input"),
    [labelPosition],
  );

  const [inputValue, setInputValue] = useState("");

  return (
    <div data-lk-component="text-input" {...textInputProps}>
      {labelPosition === "default" && (
        <label htmlFor={name} className="label">
          {name}
        </label>
      )}

      <div
        data-lk-text-input-el="input-wrap"
        data-lk-input-help-text={helpText ? "true" : "false"}
        data-help-text={helpText}
      >
        {labelPosition === "on-input" && (
          <label
            htmlFor={name}
            className={`body ${labelBackgroundColor ? ` bg-${labelBackgroundColor}` : ""} ${inputValue ? "on-field-with-value-set" : ""}`}
          >
            {name}
          </label>
        )}
        <input
          type="text"
          name={name}
          id={name}
          placeholder={labelPosition !== "on-input" ? placeholder : ""}
          onChange={(e) => setInputValue(e.target.value)}
          value={inputValue}
          {...restProps}
        />
        <StateLayer />
        <Icon name={endIcon} />
        {/* implementation omitted for brevity */}
      </div>

      {helpText && (
        <Row alignItems="center">
          <Icon
            name="info"
            fontClass="capline"
            color="outline"
            opticShift={true}
          />
          <Text color="outline" fontClass="caption" className="m-left-2xs">
            Help text goes here
          </Text>
        </Row>
      )}
    </div>
  );
}

[data-lk-component="text-input"] {
  display: flex;
  flex-flow: column nowrap;

  [data-lk-component="state-layer"] {
    border-radius: var(--lk-size-sm);
    font-size: inherit;
  }
}

[data-lk-component="text-input"] input {
  appearance: none;
  background: var(--lk-surface);
  border: none;
  font-size: inherit;
  line-height: inherit;
  color: inherit;
  width: 100%;
  padding: var(--lk-size-xs) var(--lk-size-sm);
  border-radius: var(--lk-size-sm);
}

[data-lk-text-input-label-position="on-input"] {
  label {
    position: absolute;
    top: 50%;
    left: var(--lk-size-sm);
    transform: translateY(-50%);
    opacity: 50%;
    pointer-events: none;
    transition:
      top 0.2s ease-out,
      font-size 0.2s ease-out,
      color 0.2s ease-out,
      letter-spacing 0.2s ease-out,
      opacity 0.2s ease-out,
      padding 0.2s ease-out,
      transform 0.2s ease-out;
  }

  label.on-field-with-value-set {
    opacity: 100%;
    top: 0;
    font-size: var(--label-font-size);
    letter-spacing: -0.004em;
    padding: 0 var(--lk-size-xs);
    transform: translate(calc(-1 * var(--lk-size-2xs)), -61.8%);
    color: var(--lk-outline);
  }
}

[data-lk-text-input-el="input-wrap"] {
  border: 1px solid var(--lk-outlinevariant);
  margin-top: calc(var(--bodyBoxHeight) * var(--lk-halfstep-dec));
  position: relative;

  border-radius: var(--lk-size-sm);
  outline: 3px solid transparent;
  outline-offset: -3px;
  transition:
    outline 0.2s ease-out,
    outline-offset 0.2s ease-out;

  &:has(input:focus-visible) {
    outline: 3px solid var(--lk-primary);
    outline-offset: 0px;

    label {
      opacity: 100%;
      top: 0;
      font-size: var(--label-font-size);
      letter-spacing: -0.004em;
      padding: 0 var(--lk-size-xs);
      transform: translate(calc(-1 * var(--lk-size-2xs)), -61.8%);
    }
  }

  &:placeholder-shown {
    color: var(--lk-outline);
  }

  [data-lk-component="icon"] {
    position: absolute;
    top: 50%;
    right: var(--lk-size-sm);
    transform: translateY(-50%);
  }
}

div[data-lk-text-input-label-position="on-input"] > [data-lk-text-input-el="input-wrap"] {
  margin-top: 0px;
}

[data-lk-component="text-input"]:focus-within {
  [data-lk-component="state-layer"] {
    display: none;
  }
}

[data-lk-input-help-text="true"] {
  margin-bottom: var(--lk-size-xs);
  color: var(--lk-outline);
}
